import org.junit.Assert;
import org.junit.Test;
import org.jsoup.Connection;
import java.net.URL;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void UrlBuilderConstructorTest() throws Exception {
        URL url = new URL("http://www.someurl.com/");
        UrlBuilder urlBuilder = new UrlBuilder(url);

        Assert.assertNotNull(urlBuilder);
    }

    @Test
    public void buildValidURLTest() throws Exception {
        URL url = new URL("http://www.someurl.com/");
        UrlBuilder urlBuilder = new UrlBuilder(url);

        URL result = urlBuilder.build();

        Assert.assertEquals(url, result);
    }

    @Test(expected = RuntimeException.class)
    public void buildNullURLTest() {
        UrlBuilder urlBuilder = new UrlBuilder(null);

        urlBuilder.build();
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValInvalidEncodingTest() throws Exception {
        URL url = new URL("http://www.someurl.com/");
        UrlBuilder urlBuilder = new UrlBuilder(url);

        Connection.KeyVal kv = Connection.KeyVal.create("name", "value", "invalid-encoding");

        urlBuilder.appendKeyVal(kv);
    }

    @Test
    public void appendKeyValValidEncodingTest() throws Exception {
        URL url = new URL("http://www.someurl.com/");
        UrlBuilder urlBuilder = new UrlBuilder(url);

        Connection.KeyVal kv = Connection.KeyVal.create("name", "value", "UTF-8");

        urlBuilder.appendKeyVal(kv);

        URL result = urlBuilder.build();

        Assert.assertTrue(result.toString().contains("name=value"));
    }

}
